#include <iostream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    string s1, s2;

    if (!(cin >> n >> s1 >> m >> s2)) {
        return 0;
    }

    int ans = 0;
    int limit = min(n, m);

    for (int i = 0; i < limit; ++i) {
